export function t(language: Language, key: string, values: Interpolation = {}): string {
  const raw = messages[language][key] ?? messages['pt-BR'][key] ?? extraMessages[language][key] ?? extraMessages['pt-BR'][key] ?? moreMessages[language][key] ?? moreMessages['pt-BR'][key] ?? assetUiMessages[language][key] ?? assetUiMessages['pt-BR'][key] ?? key;
  return raw.replace(/\{\{(\w+)\}\}/g, (_, name) => values[name] === undefined ? `{{${name}}}` : String(values[name]));
}

export function formatRelativeTime(language: Language, iso: string, now = Date.now()): string {
  const time = Date.parse(iso);
  if (!Number.isFinite(time)) return '';
  const seconds = Math.max(0, Math.round((now - time) / 1000));
  if (seconds < 45) return language === 'en-US' ? 'now' : 'agora';
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return language === 'en-US' ? `${minutes} min ago` : `há ${minutes} min`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return language === 'en-US' ? `${hours} hr ago` : `há ${hours} h`;
  const days = Math.round(hours / 24);
  if (days === 1) return language === 'en-US' ? 'yesterday' : 'ontem';
  if (days < 7) return language === 'en-US' ? `${days} days ago` : `há ${days} dias`;
  return formatDate(language, time, { day: '2-digit', month: '2-digit' });
}

/** Mensagem com singular/plural explícitos: `um|vários`, escolhida pelo count. */
export function tp(language: Language, key: string, count: number, values: Interpolation = {}): string {
  const raw = messages[language][key] ?? messages['pt-BR'][key] ?? key;
  const parts = raw.split('|');
  const selected = parts[count === 1 ? 0 : Math.min(1, parts.length - 1)];
  return selected.replace(/\{\{(\w+)\}\}/g, (_, name) => values[name] === undefined ? String(name === 'count' ? count : `{{${name}}}`) : String(values[name]));
}

export function formatDate(language: Language, value: number | string | Date, options?: Intl.DateTimeFormatOptions): string {
  return new Intl.DateTimeFormat(language, options).format(new Date(value));
}

export function formatNumber(language: Language, value: number, options?: Intl.NumberFormatOptions): string {
  return new Intl.NumberFormat(language, options).format(value);
}
